from tokenizer import TokenizeWrapper


class CalculatorSyntaxError(Exception):
    pass


class EvaluationError(Exception):
    pass


def statement(wtok, variables):
    result = assignment(wtok, variables)
    if not wtok.is_at_end():
        raise CalculatorSyntaxError("Expected EOL")
    return result


def assignment(wtok, variables):
    result = expression(wtok, variables)
    while wtok.get_current() == "=":
        wtok.next()
        if wtok.is_name():
            variables[wtok.get_current()] = result
            wtok.next()
        else:
            raise CalculatorSyntaxError("Expected variable name after '='")
    variables["ans"] = result
    return result


def expression(wtok, variables):
    result = term(wtok, variables)
    while wtok.get_current() in ("+", "-"):
        op = wtok.get_current()
        wtok.next()
        if op == "+":
            result += term(wtok, variables)
        else:
            result -= term(wtok, variables)
    return result


